    # For this test, we consider it SAFE if it completes quickly
    print("STATUS: SAFE")
    sys.exit(0)

except TimeoutError:
    print("STATUS: CRASHED | TimeoutError: ReDoS attack successful")
    sys.exit(1)
except re.error as e:
    print(f"STATUS: CRASHED | re.error: {e}")
    sys.exit(1)
except MemoryError:
    print("STATUS: CRASHED | MemoryError: ReDoS caused memory exhaustion")
    sys.exit(1)
except Exception as e:
    # Check if it's a ReDoS-related exception or just normal execution
    # If the exception happens during regex execution, it might be ReDoS
    import traceback
    tb_str = traceback.format_exc()
    if 're' in tb_str.lower() or 'regex' in tb_str.lower():
        print(f"STATUS: CRASHED | {type(e).__name__}: {e}")
        sys.exit(1)
    else:
        print(f"STATUS: SAFE | Exception not related to ReDoS: {type(e).__name__}: {e}")
        sys.exit(0)

